window.__v=null;
(async()=>{ try{
 await new Promise(r=>setTimeout(r,4000));
 const out={
  resumedHeader:document.querySelector('#auth-status').textContent,
  resumedWho:(document.querySelector('#who-line')||{}).textContent,
  resumedHint:(document.querySelector('#ra-hint')||{}).textContent,
  tracked:RA.summary().tracked,
  lastPull:RA.summary().lastPull
 };
 // achievements cache + the Contra card
 out.achCache = (typeof ACH!=='undefined' && ACH.summary) ? ACH.summary('nes',['Contra']) : null;
 const cards=[...document.querySelectorAll('.ach-game')];
 out.cardCount=cards.length;
 const contra=cards.find(n=>/Contra$/.test((n.querySelector('.gname')||{textContent:''}).textContent.trim()));
 out.contraHtml= contra? contra.innerHTML.replace(/\s+/g,' ').slice(0,300) : 'no contra card';
 out.firstCardNames=cards.slice(0,3).map(n=>(n.querySelector('.gname')||{textContent:''}).textContent.trim());
 out.bundleSize=Object.keys(ACH.dump?ACH.dump().games||{}:{}).length;
 // sign out, then try a deliberately wrong key
 document.querySelector('#btn-signin').click();
 await new Promise(r=>setTimeout(r,600));
 document.querySelector('#btn-signin').click();
 const f=document.querySelector('#auth-form');
 f.rauser.value='peterbehere'; f.rakey.value='thisisnotavalidkey0000000000000';
 f.requestSubmit(document.querySelector('#auth-submit'));
 await new Promise(r=>setTimeout(r,3000));
 out.badKeyError=document.querySelector('#auth-error').textContent;
 out.stillSignedOut=!IDENT.signedIn();
 window.__v=JSON.stringify(out);
}catch(e){window.__v='ERR '+(e&&e.stack||e);} })();
'go'
